#include <stdio.h>



int main(void) {
    int n, a[15][15] = {{0}};
    scanf("%d", &n);
    int row = 0, col = n / 2;
    for (int value = 1; value <= n*n; value++) {
        a[row][col] = value;
        int next_row = (row + n - 1) % n, next_col = (col + 1) % n;
        if (a[next_row][next_col]) row = (row + 1) % n;
        else { row = next_row; col = next_col; }
    }
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++)
        printf("%d%c", a[i][j], j + 1 == n ? '\n' : ' ');
    return 0;
}
